/*!50003 CREATE*/ /*!50017 DEFINER=`sa`@`%`*/ /*!50003 TRIGGER utrigger_Rera_RenewalAgent_EventRecord_INSERT
AFTER INSERT ON
tbl_rera_authdesk_agent_renewal_eventaction
FOR EACH ROW
BEGIN
      
     DECLARE v_AgentID BigInt; 
     DECLARE v_RenewalAgentID BigInt;
     DECLARE v_RnAgent_SequenceID Int;
     DECLARE v_RnAgent_YearID Int;
     DECLARE v_RnAgentDiaryNumber varchar(100); 
     DECLARE v_AgentRegistrationNumber varchar(100);
     DECLARE v_EventType int;
     
     DECLARE varchk_isdraft_membervalue int;
     DECLARE varchk_isdraft_doclistvalue int;
     
      SET v_AgentID=NEW.Related_Agent_ID;         
      SET v_RenewalAgentID=NEW.Related_RenewalAgent_ID;           
      SET v_RnAgent_SequenceID=NEW.Related_RenewalAgent_SequenceID;            
      SET v_RnAgent_YearID=NEW.Related_RenewalAgent_Year;
      SET v_RnAgentDiaryNumber=NEW.RelatedAgent_RenewalDiaryNumber;
      SET v_AgentRegistrationNumber=NEW.RERAnumberRegistration;
      SET v_EventType=NEW.EventAction_Type;
     
-- Activate ReApply Details          
If v_EventType = 290007   
then
   update tbl_rera_agent_renewal_regdiarynumber set IsDraft=0, IsLock=0 where Agent_ID=v_AgentID and AgentRenewal_ID=v_RenewalAgentID and RenewalOrderSequence=v_RnAgent_SequenceID and AgentRenewal_Year=v_RnAgent_YearID and IsActive=1;   
   
   update tbl_rera_agent_renewal_profile set IsDraft=4, IsLock=0 where Related_Agent_ID=v_AgentID and RenewalAgent_ID=v_RenewalAgentID and RenewalOrderSequence=v_RnAgent_SequenceID and RelatedRenewalAgent_Year=v_RnAgent_YearID and IsActive=1 and IsDraft=5;
   update tbl_rera_agent_renewal_othermemberdetail set IsDraft=4, IsLock=0 where Related_Agent_ID=v_AgentID and Related_RenewalAgent_ID=v_RenewalAgentID and Related_RenewalOrderSequence=v_RnAgent_SequenceID and Related_RelatedRenewalAgent_Year=v_RnAgent_YearID and IsActive=1 and IsDraft=5;
   update tbl_rera_agent_renewal_documents set IsDraft=4, IsLock=0 where Related_Agent_ID=v_AgentID and Related_RenewalAgent_ID=v_RenewalAgentID and Related_RenewalOrderSequence=v_RnAgent_SequenceID and Related_RelatedRenewalAgent_Year=v_RnAgent_YearID and IsActive=1 and IsDraft=5;
   update tbl_rera_agent_renewal_otherstateut_regreradetails set IsDraft=4, IsLock=0 where Related_Agent_ID=v_AgentID and Related_RenewalAgent_ID=v_RenewalAgentID and Related_RenewalOrderSequence=v_RnAgent_SequenceID and Related_RelatedRenewalAgent_Year=v_RnAgent_YearID and IsActive=1 and IsDraft=5;
   update tbl_rera_agent_renewal_payment set IsDraft=4, IsLock=0 where Related_Agent_ID=v_AgentID and Related_RenewalAgent_ID=v_RenewalAgentID and Related_RenewalOrderSequence=v_RnAgent_SequenceID and Related_RelatedRenewalAgent_Year=v_RnAgent_YearID and IsActive=1 and IsDraft=5;
   -- update tbl_rera_agent_renewal_paymentgateway set IsDraft=0, IsLock=0 where Related_Agent_ID=v_AgentID and Related_RenewalAgent_ID=v_RenewalAgentID and Related_RenewalOrderSequence=v_RnAgent_SequenceID and Related_RelatedRenewalAgent_Year=v_RnAgent_YearID and IsActive=1;
   
   select count(*) into varchk_isdraft_doclistvalue from tbl_rera_agent_renewal_documents where Related_Agent_ID=v_AgentID and Related_RenewalAgent_ID=v_RenewalAgentID and Related_RenewalOrderSequence=v_RnAgent_SequenceID and Related_RelatedRenewalAgent_Year=v_RnAgent_YearID and IsActive=1 and IsDraft in (4,5);
   if (varchk_isdraft_doclistvalue > 0)
   then   
		update tbl_rera_agent_renewal_documents set IsLock=0 where Related_Agent_ID=v_AgentID and Related_RenewalAgent_ID=v_RenewalAgentID and Related_RenewalOrderSequence=v_RnAgent_SequenceID and Related_RelatedRenewalAgent_Year=v_RnAgent_YearID and IsActive=1 and IsDraft in (1,4,5,6);
   end if;
   
   -- -- Reminder Scheduler (Emails and SMS)
   -- call usp_insert_tbl_rera_agent_reminderscheduler_emails(v_AgentId, v_RenewalAgentId, v_AgentDiaryNumber, v_RenewalAgentDiaryNumber, v_EventType);
   -- call usp_insert_tbl_rera_agent_reminderscheduler_smsgateway(v_AgentId, v_RenewalAgentId, v_AgentDiaryNumber, v_RenewalAgentDiaryNumber, v_EventType);
end if;
 
-- No Reply Found from Agent  
If v_EventType = 290029  
then
